<?php
declare(strict_types=1);
function form_start(string $title,string $error=''): void { ?><!doctype html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?=h($title)?> | F-06</title><link rel="stylesheet" href="/fonts/fonts.css"><style>body{margin:0;background:#f6f7f8;color:#171717;font:18px 'Hind Siliguri',sans-serif}.box{max-width:540px;margin:45px auto;padding:28px;background:white;border-radius:16px;box-shadow:0 4px 24px #0001}label{display:block;margin-top:18px}input{display:block;width:100%;box-sizing:border-box;font:inherit;padding:12px;border:1px solid #bbb;border-radius:8px}button{font:inherit;background:#b92332;color:white;border:0;border-radius:8px;padding:12px 24px;margin-top:22px;cursor:pointer}a{color:#9d1927}.error{background:#fee;padding:14px}.fine{font-size:15px;color:#555}@media(max-width:600px){.box{margin:20px 12px}}</style></head><body><main class="box"><a href="/">সাইটে ফিরুন</a><h1><?=h($title)?></h1><?php if($error):?><p class="error" role="alert"><?=h($error)?></p><?php endif; }
function form_end(): void {echo '</main></body></html>';}
